void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale if activity grows too large to avoid overflow
    const double ACTIVITY_LIMIT = 1e100;
    if (activity[var] > ACTIVITY_LIMIT) {
        const double RESCALE_FACTOR = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FACTOR;
        var_inc *= RESCALE_FACTOR;
    }

    // Keep VSIDS heap consistent: update if present, otherwise insert
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}

